    67→interface PaletteDragItem {
    68→	type: "palette";
    69→	questionType: Question["type"];
    70→}
    71→
    72→interface QuestionDragItem {
    73→	type: "question";
    74→	id: string;
    75→}
    76→
    77→type DragItem = PaletteDragItem | QuestionDragItem;
    78→
    79→interface SurveyBuilderProps {
    80→	survey: Survey;
    81→	questions: Question[];
    82→	className?: string;
    83→}
    84→
    85→export function SurveyBuilder({
    86→	survey,
    87→	questions: initialQuestions,
    88→	className,
    89→}: SurveyBuilderProps) {
    90→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    91→		null,
    92→	);
    93→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
    94→	const [questions, setQuestions] = useState(initialQuestions);
    95→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
    96→	const [overId, setOverId] = useState<string | null>(null);
    97→	const [paletteOpen, setPaletteOpen] = useState(false);
    98→	const [propertiesOpen, setPropertiesOpen] = useState(false);
    99→
   100→	// Responsive breakpoints
   101→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   102→
   103→	const queryClient = useQueryClient();
   104→
   105→	// Sync state when initialQuestions changes
   106→	useEffect(() => {
   107→		setQuestions(initialQuestions);
   108→	}, [initialQuestions]);
   109→
   110→	// Reorder mutation
   111→	const reorderMutation = useMutation(
   112→		orpc.question.reorder.mutationOptions({
   113→			onSuccess: () => {
   114→				queryClient.invalidateQueries({ queryKey: ["question"] });
   115→			},
   116→			onError: (error) => {
   117→				toast.error(error.message || "Failed to reorder questions");
   118→			},
   119→		}),
   120→	);
   121→
   122→	// DnD sensors
   123→	const sensors = useSensors(
   124→		useSensor(PointerSensor, {
   125→			activationConstraint: {
   126→				distance: 5,
   127→			},
   128→		}),
   129→		useSensor(KeyboardSensor, {
   130→			coordinateGetter: sortableKeyboardCoordinates,
   131→		}),
   132→	);
   133→
   134→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   135→	const collisionDetection: CollisionDetection = (args) => {
   136→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   137→		if (args.active.data.current?.questionType) {
   138→			const pointerCollisions = pointerWithin(args);
   139→			if (pointerCollisions.length > 0) {
   140→				return pointerCollisions;
   141→			}
   142→		}
   143→		// For canvas reordering, use closestCenter for better sortable behavior
   144→		return closestCenter(args);
   145→	};
   146→
   147→	const handleDragStart = (event: DragStartEvent) => {
   148→		const { active } = event;
   149→		const data = active.data.current;
   150→
   151→		if (data?.questionType) {
   152→			// Dragging from palette
   153→			setActiveDragItem({
   154→				type: "palette",
   155→				questionType: data.questionType as Question["type"],
   156→			});
   157→		} else {
   158→			// Dragging existing question
   159→			setActiveDragItem({
   160→				type: "question",
   161→				id: active.id as string,
   162→			});
   163→		}
   164→	};
   165→
   166→	const handleDragOver = (event: DragOverEvent) => {
   167→		const { over } = event;
   168→		setOverId(over?.id as string | null);
   169→	};
   170→
   171→	const handleDragEnd = (event: DragEndEvent) => {
   172→		const { active, over } = event;
   173→		setOverId(null);
   174→
   175→		if (!over) {
   176→			setActiveDragItem(null);
   177→			return;
   178→		}
   179→
   180→		// Handle cancel drop
   181→		if (over.id === "palette-cancel-zone") {
   182→			setActiveDragItem(null);
   183→			return;
   184→		}
   185→
   186→		// Handle palette drop (from question type palette) - use tracked drop index
   187→		if (active.data.current?.questionType) {
   188→			const questionType = active.data.current.questionType as Question["type"];
   189→
   190→			// Calculate insert index based on over.id
   191→			const overIndex = questions.findIndex((q) => q.id === over.id);
   192→			const insertIndex = overIndex === -1 ? questions.length : overIndex;
   193→
   194→			// Optimistic update
   195→			const tempId = `temp-${crypto.randomUUID()}`;
   196→			const mockQuestion = createMockQuestion(questionType);
   197→			const optimisticQuestion = { ...mockQuestion, id: tempId };
   198→
   199→			const optimisticQuestions = [
   200→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   201→				{ ...optimisticQuestion, order: insertIndex },
   202→				...questions
   203→					.slice(insertIndex)
   204→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   205→			];
   206→
   207→			setQuestions(optimisticQuestions);
   208→			setSelectedQuestionId(tempId);
   209→
   210→			// Create question and reorder
   211→			client.question
   212→				.create({
   213→					surveyId: survey.id,
   214→					type: questionType,
   215→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   216→					order: insertIndex,
   217→				})
   218→				.then((newQuestion) => {
   219→					// Replace optimistic question with real one
   220→					setQuestions((currentQuestions) => {
   221→						const updatedQuestions = currentQuestions.map((q) =>
   222→							q.id === tempId ? newQuestion : q,
   223→						);
   224→						return updatedQuestions;
   225→					});
   226→
   227→					setSelectedQuestionId((currentId) =>
   228→						currentId === tempId ? newQuestion.id : currentId,
   229→					);
   230→
   231→					queryClient.invalidateQueries({ queryKey: ["question"] });
   232→
   233→					// Reorder all questions on backend to ensure consistency
   234→					const finalQuestions = [
   235→						...questions
   236→							.slice(0, insertIndex)
   237→							.map((q, i) => ({ ...q, order: i })),
   238→						{ ...newQuestion, order: insertIndex },
   239→						...questions
   240→							.slice(insertIndex)
   241→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   242→					];
   243→
   244→					reorderMutation.mutate({
   245→						questions: finalQuestions.map((q) => ({
   246→							id: q.id,
   247→							order: q.order,
   248→						})),
   249→					});
   250→
   251→					toast.success("Question added");
   252→				})
   253→				.catch((error: Error) => {
   254→					// Revert on error
   255→					setQuestions(questions);
   256→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   257→					toast.error(error.message || "Failed to create question");
   258→				});
   259→
   260→			setActiveDragItem(null);
   261→			return;
   262→		}
   263→
   264→		// Handle reordering
   265→		if (active.id !== over.id && over.id !== "canvas") {
   266→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   267→			const newIndex = questions.findIndex((q) => q.id === over.id);
   268→
   269→			if (oldIndex !== -1 && newIndex !== -1) {
   270→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   271→					(q, index) => {
   272→						// Only create new object if order actually changed
   273→						if (q.order === index) {
   274→							return q; // Preserve reference
   275→						}
   276→						return { ...q, order: index };
   277→					},
   278→				);
   279→
   280→				setQuestions(newQuestions);
   281→
   282→				reorderMutation.mutate({
   283→					questions: newQuestions.map((q) => ({
   284→						id: q.id,
   285→						order: q.order,
   286→					})),
   287→				});
   288→			}
   289→		}
   290→
   291→		setActiveDragItem(null); // Always called last
   292→	};
   293→
   294→	const contextValue: SurveyBuilderContextValue = {
   295→		survey,
   296→		questions,
   297→		selectedQuestionId,
   298→		setSelectedQuestionId,
   299→		activeTab,
   300→		setActiveTab,
   301→		onQuestionsChange: setQuestions,
   302→		paletteOpen,
   303→		setPaletteOpen,
   304→		propertiesOpen,
   305→		setPropertiesOpen,
   306→	};
   307→
   308→	const safeQuestions = questions || [];
   309→
   310→	// Render drag overlay
   311→	const renderDragOverlay = () => {
   312→		if (!activeDragItem) return null;
   313→
   314→		if (activeDragItem.type === "palette") {
   315→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   316→			return (
   317→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   318→					<QuestionCardContent
   319→						question={mockQuestion}
   320→						isSelected={false}
   321→						hasLogic={false}
   322→						isOverlay={true}
   323→					/>
   324→				</div>
   325→			);
   326→		}
   327→
   328→		// Dragging existing question
   329→		const activeQuestion = safeQuestions.find(
   330→			(q) => q.id === activeDragItem.id,
   331→		);
   332→		if (activeQuestion) {
   333→			return (
   334→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   335→					<QuestionCardContent
   336→						question={activeQuestion}
   337→						isSelected={selectedQuestionId === activeQuestion.id}
   338→						hasLogic={false}
   339→						isOverlay={true}
   340→					/>
   341→				</div>
   342→			);
   343→		}
   344→
   345→		return null;
   346→	};
   347→
   348→	return (
   349→		<SurveyBuilderContext.Provider value={contextValue}>
   350→			<DndContext
   351→				sensors={sensors}
   352→				collisionDetection={collisionDetection}
   353→				onDragStart={handleDragStart}
   354→				onDragOver={handleDragOver}
   355→				onDragEnd={handleDragEnd}
   356→			>
   357→				<div className={cn("flex h-full flex-col", className)}>
   358→					<BuilderHeader
   359→						leftActions={
   360→							!isDesktop &&
   361→							activeTab === "build" && (
   362→								<div className="flex items-center gap-1">
   363→									<Button
   364→										variant="ghost"
   365→										size="icon"
   366→										onClick={() => setPaletteOpen(!paletteOpen)}
   367→									>
   368→										<PanelLeftClose className="h-4 w-4" />
   369→									</Button>
   370→								</div>
   371→							)
   372→						}
   373→						rightActions={
   374→							!isDesktop &&
   375→							activeTab === "build" && (
   376→								<div className="flex items-center gap-1">
   377→									<Button
   378→										variant="ghost"
   379→										size="icon"
   380→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   381→									>
   382→										<PanelRightClose className="h-4 w-4" />
   383→									</Button>
   384→								</div>
   385→							)
   386→						}
   387→					/>
   388→					<div className="flex flex-1 overflow-hidden">
   389→						{/* Left Palette - Responsive */}
   390→						{activeTab === "build" && (
   391→							<>
   392→								{/* Desktop: Fixed sidebar */}
   393→								{isDesktop && <QuestionPalette />}
   394→
   395→								{/* Tablet/Mobile: Sheet overlay */}
   396→								{!isDesktop && (
   397→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   398→										<SheetContent side="left" className="w-72 p-0">
   399→											<QuestionPalette />
   400→										</SheetContent>
   401→									</Sheet>
   402→								)}
   403→							</>
   404→						)}
   405→
   406→						{/* Canvas */}
   407→						<BuilderCanvas
   408→							questions={questions}
   409→							onQuestionsChange={setQuestions}
   410→							activeDragItem={activeDragItem}
   411→							overId={overId}
   412→						/>
   413→
   414→						{/* Right Properties Panel - Responsive */}
   415→						{activeTab === "build" && (
   416→							<>
   417→								{/* Desktop: Fixed sidebar */}
   418→								{isDesktop && <PropertiesPanel />}
   419→
   420→								{/* Tablet/Mobile: Sheet overlay */}
   421→								{!isDesktop && (
   422→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   423→										<SheetContent side="right" className="w-80 p-0">
   424→											<PropertiesPanel />
   425→										</SheetContent>
   426→									</Sheet>
   427→								)}
   428→							</>
   429→						)}
   430→					</div>
   431→				</div>
   432→
   433→				<DragOverlay dropAnimation={defaultDropAnimation}>
   434→					{renderDragOverlay()}
   435→				</DragOverlay>
   436→			</DndContext>
   437→		</SurveyBuilderContext.Provider>
   438→	);
   439→}
   440→
   441→export { BuilderCanvas } from "./builder-canvas";
   442→// Re-export sub-components for compound pattern
   443→export { BuilderHeader } from "./builder-header";
   444→export { PropertiesPanel } from "./properties-panel";
   445→export { QuestionPalette } from "./question-palette";
   446→

