     1→import type {
     2→	LogicRule,
     3→	LogicOperator,
     4→	LogicAction,
     5→	Question,
     6→} from "@orksys-survey/db";
     7→
     8→/**
     9→ * Represents an answer value in the survey response system.
    10→ * Can be a primitive value, an array (for checkboxes), or null/undefined.
    11→ */
    12→export type AnswerValue = unknown;
    13→
    14→/**
    15→ * Map of question IDs to their answer values.
    16→ */
    17→export type AnswersMap = Map<string, AnswerValue> | Record<string, AnswerValue>;
    18→
    19→/**
    20→ * Result of evaluating a single logic rule.
    21→ */
    22→export interface RuleEvaluationResult {
    23→	ruleId: string;
    24→	matches: boolean;
    25→	action: LogicAction;
    26→	targetQuestionId?: string | null;
    27→}
    28→
    29→/**
    30→ * Result of evaluating all logic rules for the current state.
    31→ */
    32→export interface LogicEvaluationResult {
    33→	/**
    34→	 * Set of question IDs that should be visible based on current answers.
    35→	 * Questions not in this set should be hidden.
    36→	 */
    37→	visibleQuestionIds: Set<string>;
    38→
    39→	/**
    40→	 * Navigation action to apply, if any.
    41→	 */
    42→	navigationAction: {
    43→		type: "jump_to" | "skip" | "end_survey";
    44→		targetQuestionId?: string;
    45→	} | null;
    46→
    47→	/**
    48→	 * Whether the survey should end early based on logic rules.
    49→	 */
    50→	shouldEndSurvey: boolean;
    51→
    52→	/**
    53→	 * Individual rule evaluation results for debugging/logging.
    54→	 */
    55→	ruleResults: RuleEvaluationResult[];
    56→}
    57→
    58→/**
    59→ * Converts an answers map to a Record for easier access.
    60→ */
    61→function normalizeAnswers(answers: AnswersMap): Record<string, AnswerValue> {
    62→	if (answers instanceof Map) {
    63→		const record: Record<string, AnswerValue> = {};
    64→		for (const [key, value] of answers.entries()) {
    65→			record[key] = value;
    66→		}
    67→		return record;
    68→	}
    69→	return answers;
    70→}
    71→
    72→/**
    73→ * Evaluates a condition operator against an answer value and condition value.
    74→ */
    75→export function evaluateCondition(
    76→	operator: LogicOperator,
    77→	answerValue: AnswerValue,
    78→	conditionValue: unknown,
    79→): boolean {
    80→	switch (operator) {
    81→		case "equals": {
    82→			// Handle array answers (checkboxes)
    83→			if (Array.isArray(answerValue)) {
    84→				return answerValue.some((v) => v === conditionValue);
    85→			}
    86→			// Handle null/undefined
    87→			if (answerValue == null) {
    88→				return conditionValue == null || conditionValue === "";
    89→			}
    90→			// String comparison (case-insensitive for user-facing strings)
    91→			if (typeof answerValue === "string" && typeof conditionValue === "string") {
    92→				return answerValue.toLowerCase() === conditionValue.toLowerCase();
    93→			}
    94→			// Number comparison
    95→			if (typeof answerValue === "number" && typeof conditionValue === "number") {
    96→				return answerValue === conditionValue;
    97→			}
    98→			// Fallback to strict equality
    99→			return answerValue === conditionValue;
   100→		}
   101→
   102→		case "not_equals": {
   103→			return !evaluateCondition("equals", answerValue, conditionValue);
   104→		}
   105→
   106→		case "contains": {
   107→			// Handle array answers (checkboxes - check if any value contains)
   108→			if (Array.isArray(answerValue)) {
   109→				return answerValue.some((v) =>
   110→					evaluateCondition("contains", v, conditionValue),
   111→				);
   112→			}
   113→			// String contains check
   114→			if (typeof answerValue === "string" && typeof conditionValue === "string") {
   115→				return answerValue.toLowerCase().includes(conditionValue.toLowerCase());
   116→			}
   117→			// For non-strings, treat as equality check
   118→			return answerValue === conditionValue;
   119→		}
   120→
   121→		case "greater_than": {
   122→			const answerNum = Number(answerValue);
   123→			const conditionNum = Number(conditionValue);
   124→			if (Number.isNaN(answerNum) || Number.isNaN(conditionNum)) {
   125→				return false;
   126→			}
   127→			return answerNum > conditionNum;
   128→		}
   129→
   130→		case "less_than": {
   131→			const answerNum = Number(answerValue);
   132→			const conditionNum = Number(conditionValue);
   133→			if (Number.isNaN(answerNum) || Number.isNaN(conditionNum)) {
   134→				return false;
   135→			}
   136→			return answerNum < conditionNum;
   137→		}
   138→
   139→		case "is_empty": {
   140→			if (answerValue == null) return true;
   141→			if (typeof answerValue === "string") return answerValue.trim() === "";
   142→			if (Array.isArray(answerValue)) return answerValue.length === 0;
   143→			return false;
   144→		}
   145→
   146→		case "is_not_empty": {
   147→			return !evaluateCondition("is_empty", answerValue, conditionValue);
   148→		}
   149→
   150→		default:
   151→			return false;
   152→	}
   153→}
   154→
   155→/**
   156→ * Evaluates a single logic rule against the current answers.
   157→ */
   158→export function evaluateRule(
   159→	rule: LogicRule,
   160→	answers: AnswersMap,
   161→): RuleEvaluationResult {
   162→	const normalizedAnswers = normalizeAnswers(answers);
   163→	const answerValue = normalizedAnswers[rule.sourceQuestionId];
   164→
   165→	const matches = evaluateCondition(
   166→		rule.operator,
   167→		answerValue,
   168→		rule.conditionValue,
   169→	);
   170→
   171→	return {
   172→		ruleId: rule.id,
   173→		matches,
   174→		action: rule.action,
   175→		targetQuestionId: rule.targetQuestionId,
   176→	};
   177→}
   178→
   179→/**
   180→ * Evaluates all logic rules and determines visibility and navigation actions.
   181→ *
   182→ * Rules are evaluated in order, and actions are applied as follows:
   183→ * - show/hide: Accumulates to determine final visibility
   184→ * - jump_to: Returns first matching jump action
   185→ * - skip: Returns first matching skip action
   186→ * - end_survey: Returns true if any matching rule has this action
   187→ *
   188→ * @param rules - All logic rules for the survey
   189→ * @param answers - Current answers (questionId -> value mapping)
   190→ * @param allQuestionIds - All question IDs in the survey (for visibility default)
   191→ * @param currentQuestionId - The current question being displayed (for context)
   192→ * @returns Logic evaluation result with visibility, navigation, and survey end state
   193→ */
