"use client";

import { useSurveyRunner } from "./context";
import { QuestionRenderer } from "./question-renderer";

export function RunnerCanvas() {
	const { visibleQuestions, currentQuestionIndex } = useSurveyRunner();

	// Find the current visible question
	const currentVisibleIndex = Math.min(
		currentQuestionIndex,
		visibleQuestions.length - 1,
	);
	const currentQuestion = visibleQuestions[currentVisibleIndex];

	if (!currentQuestion) {
		return (
			<div className="flex flex-1 items-center justify-center">
				<p className="text-neutral-500">No questions available</p>
			</div>
		);
	}

	return (
		<div className="flex-1 overflow-y-auto px-6 py-8">
			<div className="mx-auto max-w-2xl">
				<QuestionRenderer question={currentQuestion} />
			</div>
		</div>
	);
}

"use client";

import { ArrowLeft, ArrowRight, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useSurveyRunner } from "./context";

export function RunnerNavigation() {
	const { canGoBack, canGoNext, isSubmitting, goBack, submit } = useSurveyRunner();

	return (
		<div className="border-t border-neutral-200 bg-white px-6 py-4">
			<div className="mx-auto flex max-w-2xl items-center justify-between gap-4">
				<Button
					variant="ghost"
					onClick={goBack}
					disabled={!canGoBack}
					className="text-neutral-600"
				>
					<ArrowLeft className="mr-2 h-4 w-4" />
					Back
				</Button>

				{canGoNext ? (
					<Button onClick={() => {}} className="bg-neutral-900 hover:bg-neutral-800">
						Next
						<ArrowRight className="ml-2 h-4 w-4" />
					</Button>
				) : (
					<Button
						onClick={submit}
						disabled={isSubmitting}
						className="bg-neutral-900 hover:bg-neutral-800"
					>
						{isSubmitting ? (
							<>
								<Loader2 className="mr-2 h-4 w-4 animate-spin" />
								Submitting...
							</>
						) : (
							"Submit"
						)}
					</Button>
				)}
			</div>
		</div>
	);
}

