interface SurveyRunnerProps {
	survey: Survey;
	questions: Question[];
	logicRules?: LogicRule[];
	className?: string;
	onComplete?: () => void;
}

function SurveyRunnerComponent({
	survey,
	questions,
	logicRules = [],
	className,
	onComplete,
}: SurveyRunnerProps) {
	const handleComplete = useCallback(() => {
		onComplete?.();
	}, [onComplete]);

	return (
		<SurveyRunnerProvider
			survey={survey}
			questions={questions}
			logicRules={logicRules}
			onComplete={handleComplete}
		>
			<div className={`flex h-screen flex-col ${className ?? ""}`}>
				<RunnerHeader />
				<RunnerProgress />
				<RunnerCanvas />
				<RunnerNavigation />
			</div>
		</SurveyRunnerProvider>
	);
}

