     1→"use client";
     2→
     3→import type {
     4→	LogicRule,
     5→	Question,
     6→	Survey,
     7→	SurveySettings,
     8→} from "@orksys-survey/db";
     9→import { useMutation } from "@tanstack/react-query";
    10→import { useRouter } from "next/navigation";
    11→import {
    12→	createContext,
    13→	useCallback,
    14→	useContext,
    15→	useMemo,
    16→	useState,
    17→} from "react";
    18→import { toast } from "sonner";
    19→import { client } from "@/utils/orpc";
    20→import { useFingerprint } from "./hooks/use-fingerprint";
    21→import { useLogicEvaluator } from "./hooks/use-logic-evaluator";
    22→import { validateAnswer } from "./utils/validation";
    23→
    24→export type AnswerValue = unknown;
    25→
    26→interface SurveyRunnerContextValue {
    27→	// Survey data
    28→	survey: Survey;
    29→	questions: Question[];
    30→	settings: SurveySettings | null;
    31→	logicRules: LogicRule[];
    32→
    33→	// Response state
    34→	answers: Map<string, AnswerValue>;
    35→	currentQuestionIndex: number;
    36→	visibleQuestionIds: Set<string>;
    37→	visibleQuestions: Question[];
    38→
    39→	// Navigation
    40→	canGoBack: boolean;
    41→	canGoNext: boolean;
    42→	isComplete: boolean;
    43→	isSubmitting: boolean;
    44→
    45→	// Actions
    46→	setAnswer: (questionId: string, value: AnswerValue) => void;
    47→	goNext: () => void;
    48→	goBack: () => void;
    49→	submit: () => Promise<void>;
    50→
    51→	// Metadata
    52→	fingerprint: string | null;
    53→
    54→	// Error state
    55→	currentError: string | null;
    56→	clearError: () => void;
    57→}
    58→
    59→const SurveyRunnerContext = createContext<SurveyRunnerContextValue | null>(
    60→	null,
    61→);
    62→
    63→export function useSurveyRunner() {
    64→	const context = useContext(SurveyRunnerContext);
    65→	if (!context) {
    66→		throw new Error(
    67→			"useSurveyRunner must be used within a SurveyRunner component",
    68→		);
    69→	}
    70→	return context;
    71→}
    72→
    73→interface SurveyRunnerProviderProps {
    74→	survey: Survey;
    75→	questions: Question[];
    76→	logicRules?: LogicRule[];
    77→	children: React.ReactNode;
    78→	onComplete?: () => void;
    79→}
    80→
    81→export function SurveyRunnerProvider({
    82→	survey,
    83→	questions: allQuestions,
    84→	logicRules = [],
    85→	children,
    86→	onComplete,
    87→}: SurveyRunnerProviderProps) {
    88→	const router = useRouter();
    89→	const fingerprint = useFingerprint();
    90→	const [answers, setAnswers] = useState<Map<string, AnswerValue>>(new Map());
    91→	const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    92→	const [currentError, setCurrentError] = useState<string | null>(null);
    93→	const [isComplete, setIsComplete] = useState(false);
    94→
    95→	// Sort questions by order
    96→	const sortedQuestions = useMemo(
    97→		() => [...allQuestions].sort((a, b) => a.order - b.order),
    98→		[allQuestions],
    99→	);
   100→
   101→	// Evaluate logic to determine visibility
   102→	const { visibleQuestionIds } = useLogicEvaluator({
   103→		rules: logicRules,
   104→		answers,
   105→		questions: sortedQuestions,
   106→		currentQuestionId: sortedQuestions[currentQuestionIndex]?.id,
   107→	});
   108→
   109→	// Get visible questions
   110→	const visibleQuestions = useMemo(
   111→		() => sortedQuestions.filter((q) => visibleQuestionIds.has(q.id)),
   112→		[sortedQuestions, visibleQuestionIds],
   113→	);
   114→
   115→	// Get current visible question
   116→	const currentVisibleIndex = useMemo(() => {
   117→		const currentId = sortedQuestions[currentQuestionIndex]?.id;
   118→		if (!currentId) return 0;
   119→		return visibleQuestions.findIndex((q) => q.id === currentId);
   120→	}, [sortedQuestions, currentQuestionIndex, visibleQuestions]);
   121→
   122→	const currentQuestion = visibleQuestions[currentVisibleIndex];
   123→
   124→	// Navigation state
   125→	const canGoBack = currentVisibleIndex > 0;
   126→	const canGoNext = currentVisibleIndex < visibleQuestions.length - 1;
   127→
   128→	// Submit mutation
   129→	const submitMutation = useMutation({
   130→		mutationFn: async () => {
   131→			const answersArray = Array.from(answers.entries()).map(
   132→				([questionId, value]) => ({
   133→					questionId,
   134→					value,
   135→				}),
   136→			);
   137→
   138→			return client.response.submit({
   139→				surveyId: survey.id,
   140→				fingerprint: fingerprint ?? undefined,
   141→				answers: answersArray,
   142→				isComplete: true,
   143→				metadata: {
   144→					userAgent: navigator.userAgent,
   145→					language: navigator.language,
   146→					timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
   147→				},
   148→			});
   149→		},
   150→		onSuccess: () => {
   151→			setIsComplete(true);
   152→			if (onComplete) {
   153→				onComplete();
   154→			} else {
   155→				// Navigate to complete page
   156→				const completeUrl = `/s/${survey.slug}/complete`;
   157→				const settings = survey.settings as SurveySettings | null;
   158→				if (settings?.thankYouMessage || settings?.redirectUrl) {
   159→					const params = new URLSearchParams();
   160→					if (settings.thankYouMessage) {
   161→						params.set("message", settings.thankYouMessage);
   162→					}
   163→					if (settings.redirectUrl) {
   164→						params.set("redirectUrl", settings.redirectUrl);
   165→					}
   166→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   167→					router.push(`${completeUrl}?${params.toString()}` as any);
   168→				} else {
   169→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   170→					router.push(completeUrl as any);
   171→				}
   172→			}
   173→		},
   174→		onError: (error) => {
   175→			toast.error(error.message || "Failed to submit response");
   176→		},
   177→	});
   178→
   179→	// Actions
   180→	const setAnswer = useCallback((questionId: string, value: AnswerValue) => {
   181→		setAnswers((prev) => {
   182→			const next = new Map(prev);
   183→			next.set(questionId, value);
   184→			return next;
   185→		});
   186→		setCurrentError(null);
   187→	}, []);
   188→
   189→	const goNext = useCallback(() => {
   190→		if (!currentQuestion) return;
   191→
   192→		// Validate current question
   193→		const answer = answers.get(currentQuestion.id);
   194→		const error = validateAnswer(currentQuestion, answer);
   195→		if (error) {
   196→			setCurrentError(error);
   197→			return;
   198→		}
   199→
   200→		if (canGoNext) {
   201→			const nextVisibleQuestion = visibleQuestions[currentVisibleIndex + 1];
   202→			if (nextVisibleQuestion) {
   203→				const nextIndex = sortedQuestions.findIndex(
   204→					(q) => q.id === nextVisibleQuestion.id,
   205→				);
   206→				setCurrentQuestionIndex(nextIndex);
   207→			}
   208→		}
   209→	}, [
   210→		currentQuestion,
   211→		answers,
   212→		canGoNext,
   213→		visibleQuestions,
   214→		currentVisibleIndex,
   215→		sortedQuestions,
   216→	]);
   217→
   218→	const goBack = useCallback(() => {
   219→		if (!canGoBack) return;
   220→
   221→		const prevVisibleQuestion = visibleQuestions[currentVisibleIndex - 1];
   222→		if (prevVisibleQuestion) {
   223→			const prevIndex = sortedQuestions.findIndex(
   224→				(q) => q.id === prevVisibleQuestion.id,
   225→			);
   226→			setCurrentQuestionIndex(prevIndex);
   227→		}
   228→	}, [canGoBack, visibleQuestions, currentVisibleIndex, sortedQuestions]);
   229→
   230→	const submit = useCallback(async () => {
   231→		if (!currentQuestion) return;
   232→
   233→		// Validate current question
   234→		const answer = answers.get(currentQuestion.id);
   235→		const error = validateAnswer(currentQuestion, answer);
   236→		if (error) {
   237→			setCurrentError(error);
   238→			return;
   239→		}
   240→
   241→		await submitMutation.mutateAsync();
   242→	}, [currentQuestion, answers, submitMutation]);
   243→
   244→	const clearError = useCallback(() => {
   245→		setCurrentError(null);
   246→	}, []);
   247→
   248→	const value: SurveyRunnerContextValue = {
   249→		survey,
   250→		questions: sortedQuestions,
   251→		settings: survey.settings as SurveySettings | null,
   252→		logicRules,
   253→		answers,
   254→		currentQuestionIndex,
   255→		visibleQuestionIds,
   256→		visibleQuestions,
   257→		canGoBack,
   258→		canGoNext,
   259→		isComplete,
   260→		isSubmitting: submitMutation.isPending,
   261→		setAnswer,
   262→		goNext,
   263→		goBack,
   264→		submit,
   265→		fingerprint,
   266→		currentError,
   267→		clearError,
   268→	};
   269→
   270→	return (
   271→		<SurveyRunnerContext.Provider value={value}>
   272→			{children}
   273→		</SurveyRunnerContext.Provider>
   274→	);
   275→}
   276→

