    60→// Verify survey belongs to organization
    61→async function verifySurveyAccess(
    62→	surveyId: string,
    63→	organizationId: string,
    64→): Promise<void> {
    65→	const result = await db
    66→		.select()
    67→		.from(survey)
    68→		.where(
    69→			and(eq(survey.id, surveyId), eq(survey.organizationId, organizationId)),
    70→		)
    71→		.limit(1);
