    78→export const responseRouter = {
    79→	// PUBLIC - Get published survey for runner
    80→	getSurveyForRunner: publicProcedure
    81→		.input(z.object({ slug: z.string() }))
    82→		.handler(async ({ input }) => {
    83→			const surveyResult = await db
    84→				.select()
    85→				.from(survey)
    86→				.where(and(eq(survey.slug, input.slug), eq(survey.status, "published")))
    87→				.limit(1);
    88→
    89→			if (!surveyResult[0]) {
    90→				throw new Error("Survey not found or not published");
    91→			}
    92→
    93→			// Get questions and logic rules for the survey in parallel
    94→			const [questions, logicRules] = await Promise.all([
    95→				db
    96→					.select()
    97→					.from(question)
    98→					.where(eq(question.surveyId, surveyResult[0].id))
    99→					.orderBy(question.order),
   100→				db
   101→					.select()
   102→					.from(logicRule)
   103→					.where(eq(logicRule.surveyId, surveyResult[0].id)),
   104→			]);
   105→
   106→			return {
   107→				survey: surveyResult[0],
   108→				questions,
   109→				logicRules,
   110→			};
   111→		}),
   112→
   113→	// PUBLIC - Submit response
   114→	submit: publicProcedure
   115→		.input(submitResponseSchema)
   116→		.handler(async ({ input }) => {
   117→			// Verify survey exists and is published
   118→			const surveyResult = await db
   119→				.select()
   120→				.from(survey)
   121→				.where(
   122→					and(eq(survey.id, input.surveyId), eq(survey.status, "published")),
   123→				)
   124→				.limit(1);
   125→
   126→			if (!surveyResult[0]) {
   127→				throw new Error("Survey not found or not published");
   128→			}
   129→
   130→			// Check for duplicate fingerprint if provided
   131→			if (input.fingerprint) {
   132→				const existingResponse = await db
   133→					.select()
   134→					.from(response)
   135→					.where(
   136→						and(
   137→							eq(response.surveyId, input.surveyId),
   138→							eq(response.fingerprint, input.fingerprint),
   139→						),
   140→					)
   141→					.limit(1);
   142→
   143→				if (existingResponse[0]) {
   144→					throw new Error("You have already responded to this survey");
   145→				}
   146→			}
   147→
   148→			// Verify all questions belong to this survey
   149→			const questionIds = input.answers.map((a) => a.questionId);
   150→			if (questionIds.length > 0) {
   151→				const questions = await db
   152→					.select()
   153→					.from(question)
   154→					.where(inArray(question.id, questionIds));
   155→
   156→				for (const q of questions) {
   157→					if (q.surveyId !== input.surveyId) {
   158→						throw new Error(`Question ${q.id} does not belong to this survey`);
   159→					}
   160→				}
   161→			}
   162→
   163→			// Create response and answers in a transaction
   164→			const responseId = generateResponseId();
   165→			const now = new Date();
   166→
   167→			await db.insert(response).values({
   168→				id: responseId,
   169→				surveyId: input.surveyId,
   170→				respondentId: input.respondentId ?? null,
   171→				fingerprint: input.fingerprint ?? null,
   172→				metadata: input.metadata ?? null,
   173→				isComplete: input.isComplete,
   174→				startedAt: now,
   175→				completedAt: input.isComplete ? now : null,
   176→			});
   177→
   178→			// Insert answers
   179→			if (input.answers.length > 0) {
   180→				const answersToInsert = input.answers.map((a) => ({
   181→					id: generateAnswerId(),
   182→					responseId,
   183→					questionId: a.questionId,
   184→					value: a.value,
   185→				}));
   186→
   187→				await db.insert(answer).values(answersToInsert);
   188→			}
   189→
   190→			return { success: true, responseId };
   191→		}),
   192→
   193→	// PROTECTED - List responses for a survey
   194→	list: organizationProcedure
   195→		.input(responseListSchema)
   196→		.handler(async ({ input, context }) => {
   197→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
   198→
   199→			const { page, limit, surveyId, isComplete } = input;
   200→			const offset = (page - 1) * limit;
   201→
   202→			const conditions = [eq(response.surveyId, surveyId)];
   203→			if (isComplete !== undefined) {
   204→				conditions.push(eq(response.isComplete, isComplete));
   205→			}
   206→
   207→			const [responses, totalResult] = await Promise.all([
   208→				db
   209→					.select()
   210→					.from(response)
   211→					.where(and(...conditions))
   212→					.orderBy(desc(response.createdAt))
   213→					.limit(limit)
   214→					.offset(offset),
   215→				db
   216→					.select({ count: count() })
   217→					.from(response)
   218→					.where(and(...conditions)),
   219→			]);
   220→
   221→			return {
   222→				data: responses,
   223→				pagination: {
   224→					page,
   225→					limit,
   226→					total: totalResult[0]?.count ?? 0,
   227→					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
   228→				},
   229→			};
   230→		}),
   231→
   232→	// PROTECTED - Get single response with answers
   233→	getById: organizationProcedure
   234→		.input(z.object({ id: z.string() }))
   235→		.handler(async ({ input, context }) => {
   236→			const result = await db
   237→				.select()
   238→				.from(response)
   239→				.where(eq(response.id, input.id))
   240→				.limit(1);
   241→
   242→			if (!result[0]) {
   243→				throw new Error("Response not found");
   244→			}
   245→
   246→			// Verify survey access
   247→			await verifySurveyAccess(
   248→				result[0].surveyId,
   249→				context.activeOrganization.id,
   250→			);
   251→
   252→			// Get answers - we'd need an answer table query here
   253→			// For now, return the response without answers
   254→			return result[0];
   255→		}),
   256→
   257→	// PROTECTED - Get response stats for a survey
   258→	getStats: organizationProcedure
   259→		.input(z.object({ surveyId: z.string() }))
   260→		.handler(async ({ input, context }) => {
   261→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
   262→
   263→			const [totalResult, completeResult, partialResult] = await Promise.all([
   264→				db
   265→					.select({ count: count() })
   266→					.from(response)
   267→					.where(eq(response.surveyId, input.surveyId)),
   268→				db
   269→					.select({ count: count() })
   270→					.from(response)
   271→					.where(
   272→						and(
   273→							eq(response.surveyId, input.surveyId),
   274→							eq(response.isComplete, true),
   275→						),
   276→					),
   277→				db
   278→					.select({ count: count() })
   279→					.from(response)
   280→					.where(
   281→						and(
   282→							eq(response.surveyId, input.surveyId),
   283→							eq(response.isComplete, false),
   284→						),
   285→					),
   286→			]);
   287→
   288→			return {
   289→				total: totalResult[0]?.count ?? 0,
   290→				complete: completeResult[0]?.count ?? 0,
   291→				partial: partialResult[0]?.count ?? 0,
   292→			};
   293→		}),
   294→
   295→	// PROTECTED - Delete single response
   296→	delete: adminProcedure
   297→		.input(z.object({ id: z.string() }))
   298→		.handler(async ({ input, context }) => {
   299→			const result = await db
   300→				.select()
   301→				.from(response)
   302→				.where(eq(response.id, input.id))
   303→				.limit(1);
   304→
   305→			if (!result[0]) {
   306→				throw new Error("Response not found");
   307→			}
   308→
   309→			await verifySurveyAccess(
   310→				result[0].surveyId,
   311→				context.activeOrganization.id,
   312→			);
   313→
   314→			await db.delete(response).where(eq(response.id, input.id));
   315→			return { success: true };
   316→		}),
   317→
   318→	// PROTECTED - Bulk delete responses
   319→	bulkDelete: adminProcedure
   320→		.input(z.object({ ids: z.array(z.string()) }))
   321→		.handler(async ({ input, context }) => {
   322→			if (input.ids.length === 0) {
   323→				return { success: true, deletedCount: 0 };
   324→			}
   325→
   326→			const responses = await db
   327→				.select()
   328→				.from(response)
   329→				.where(inArray(response.id, input.ids));
   330→
   331→			if (responses.length !== input.ids.length) {
   332→				throw new Error("Some responses not found");
   333→			}
   334→
   335→			// Verify survey access for first response
   336→			const firstResponse = responses[0];
   337→			if (!firstResponse) {
   338→				throw new Error("No responses found");
   339→			}
   340→			await verifySurveyAccess(
   341→				firstResponse.surveyId,
   342→				context.activeOrganization.id,
   343→			);
   344→
   345→			await db.delete(response).where(inArray(response.id, input.ids));
   346→
   347→			return { success: true, deletedCount: responses.length };
   348→		}),
   349→};
