   231→					queryClient.invalidateQueries({ queryKey: ["question"] });
   232→
   233→					// Reorder all questions on backend to ensure consistency
   234→					const finalQuestions = [
   235→						...questions
   236→							.slice(0, insertIndex)
   237→							.map((q, i) => ({ ...q, order: i })),
   238→						{ ...newQuestion, order: insertIndex },
   239→						...questions
   240→							.slice(insertIndex)
   241→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   242→					];
