   295→		survey,
   296→		questions,
   297→		selectedQuestionId,
   298→		setSelectedQuestionId,
   299→		activeTab,
   300→		setActiveTab,
   301→		onQuestionsChange: setQuestions,
   302→		paletteOpen,
   303→		setPaletteOpen,
   304→		propertiesOpen,
   305→		setPropertiesOpen,
   306→	};
   307→
   308→	const safeQuestions = questions || [];
   309→
   310→	// Render drag overlay
   311→	const renderDragOverlay = () => {
   312→		if (!activeDragItem) return null;
