   324→				</div>
   325→			);
   326→		}
   327→
   328→		// Dragging existing question
   329→		const activeQuestion = safeQuestions.find(
   330→			(q) => q.id === activeDragItem.id,
   331→		);
   332→		if (activeQuestion) {
   333→			return (
   334→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   335→					<QuestionCardContent
   336→						question={activeQuestion}
   337→						isSelected={selectedQuestionId === activeQuestion.id}
   338→						hasLogic={false}
   339→						isOverlay={true}
   340→					/>
   341→				</div>
   342→			);
   343→		}
   344→
   345→		return null;
   346→	};
   347→
   348→	return (
   349→		<SurveyBuilderContext.Provider value={contextValue}>
   350→			<DndContext
   351→				sensors={sensors}
   352→				collisionDetection={collisionDetection}
   353→				onDragStart={handleDragStart}
   354→				onDragOver={handleDragOver}
   355→				onDragEnd={handleDragEnd}
   356→			>
   357→				<div className={cn("flex h-full flex-col", className)}>
   358→					<BuilderHeader
   359→						leftActions={
   360→							!isDesktop &&
   361→							activeTab === "build" && (
   362→								<div className="flex items-center gap-1">
   363→									<Button
   364→										variant="ghost"
   365→										size="icon"
   366→										onClick={() => setPaletteOpen(!paletteOpen)}
   367→									>
   368→										<PanelLeftClose className="h-4 w-4" />
   369→									</Button>
   370→								</div>
   371→							)
   372→						}
   373→						rightActions={
   374→							!isDesktop &&
   375→							activeTab === "build" && (
   376→								<div className="flex items-center gap-1">
   377→									<Button
   378→										variant="ghost"
   379→										size="icon"
   380→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   381→									>
   382→										<PanelRightClose className="h-4 w-4" />
   383→									</Button>
   384→								</div>
   385→							)
   386→						}
   387→					/>
   388→					<div className="flex flex-1 overflow-hidden">
   389→						{/* Left Palette - Responsive */}
   390→						{activeTab === "build" && (
   391→							<>
   392→								{/* Desktop: Fixed sidebar */}
   393→								{isDesktop && <QuestionPalette />}
   394→
   395→								{/* Tablet/Mobile: Sheet overlay */}
   396→								{!isDesktop && (
   397→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   398→										<SheetContent side="left" className="w-72 p-0">
   399→											<QuestionPalette />
   400→										</SheetContent>
   401→									</Sheet>
   402→								)}
   403→							</>
   404→						)}
   405→
   406→						{/* Canvas */}
   407→						<BuilderCanvas
   408→							questions={questions}
   409→							onQuestionsChange={setQuestions}
   410→							activeDragItem={activeDragItem}
   411→							overId={overId}
   412→						/>
   413→
   414→						{/* Right Properties Panel - Responsive */}
   415→						{activeTab === "build" && (
   416→							<>
   417→								{/* Desktop: Fixed sidebar */}
   418→								{isDesktop && <PropertiesPanel />}
   419→
   420→								{/* Tablet/Mobile: Sheet overlay */}
   421→								{!isDesktop && (
   422→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   423→										<SheetContent side="right" className="w-80 p-0">
   424→											<PropertiesPanel />
   425→										</SheetContent>
   426→									</Sheet>
   427→								)}
   428→							</>
   429→						)}
   430→					</div>
   431→				</div>
   432→
   433→				<DragOverlay dropAnimation={defaultDropAnimation}>
   434→					{renderDragOverlay()}
   435→				</DragOverlay>
   436→			</DndContext>
   437→		</SurveyBuilderContext.Provider>
   438→	);
   439→}
